#include <stdio.h>

int main() {
    char str[100];
    int i = 0, len = 0, isPalindrome = 1;

    printf("Enter a word: ");
    scanf("%s", str);

    while(str[len] != '\0') {
        len++;
    }

    for(i=0; i < len/2; i++) {
        if(str[i] != str[len-i-1]) {
            isPalindrome = 0;
            break;
        }
    }

    if(isPalindrome == 1) {
        printf("The word is a palindrome.\n");
    } else {
        printf("The word is not a palindrome.\n");
    }

    return 0;
}

